css:
.oi { width: 300px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.oi-label { display: block; margin-bottom: 6px; font-size: 13px; font-weight: 600; color: #374151; }
.oi-input { width: 100%; padding: 11px 14px; box-sizing: border-box; border: 1px solid #d1d5db; border-radius: 8px; background: #fff; font-size: 14px; color: #111827; transition: border-color 0.15s, box-shadow 0.15s; }
.oi-input::placeholder { color: #9ca3af; }
.oi-input:hover { border-color: #9ca3af; }
.oi-input:focus { outline: none; border-color: #2563eb; box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.18); }

.fi { width: 300px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.fi-label { display: block; margin-bottom: 6px; font-size: 13px; font-weight: 600; color: #374151; }
.fi-input { width: 100%; padding: 12px 14px; box-sizing: border-box; border: 2px solid transparent; border-radius: 10px; background: #f3f4f6; font-size: 14px; color: #111827; transition: background 0.15s, border-color 0.15s; }
.fi-input:hover { background: #e5e7eb; }
.fi-input:focus { outline: none; background: #fff; border-color: #6366f1; }

.ui { width: 300px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.ui-label { display: block; font-size: 12px; font-weight: 600; color: #6b7280; }
.ui-input { width: 100%; padding: 8px 2px; box-sizing: border-box; border: 0; border-bottom: 2px solid #d1d5db; border-radius: 0; background: transparent; font-size: 15px; color: #111827; transition: border-color 0.2s; }
.ui-input:focus { outline: none; border-bottom-color: #10b981; }

.ci { width: 300px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.ci-label { display: block; margin-bottom: 6px; font-size: 13px; font-weight: 600; color: #374151; }
.ci-wrap { position: relative; }
.ci-icon { position: absolute; top: 50%; left: 13px; transform: translateY(-50%); font-size: 14px; opacity: 0.6; }
.ci-input { width: 100%; padding: 11px 14px 11px 38px; box-sizing: border-box; border: 1px solid #d1d5db; border-radius: 8px; background: #fff; font-size: 14px; }
.ci-input:focus { outline: none; border-color: #2563eb; box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.18); }

.pi { position: relative; width: 300px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.pi-input { width: 100%; padding: 13px 52px 13px 20px; box-sizing: border-box; border: 1px solid #e5e7eb; border-radius: 999px; background: #fff; box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06); font-size: 14px; }
.pi-input:focus { outline: none; border-color: #a5b4fc; box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.2); }
.pi-btn { position: absolute; top: 50%; right: 6px; width: 36px; height: 36px; transform: translateY(-50%); border: 0; border-radius: 50%; background: #6366f1; color: #fff; font-size: 13px; cursor: pointer; }
.pi-btn:hover { background: #4f46e5; }

.fl { position: relative; width: 300px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.fl-input { width: 100%; padding: 22px 14px 8px; box-sizing: border-box; border: 1px solid #d1d5db; border-radius: 10px; background: #fff; font-size: 15px; color: #111827; }
.fl-input:focus { outline: none; border-color: #2563eb; box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.18); }
.fl-label { position: absolute; top: 50%; left: 15px; transform: translateY(-50%); font-size: 15px; color: #9ca3af; pointer-events: none; transition: top 0.15s, font-size 0.15s, color 0.15s; }
.fl-input:focus + .fl-label, .fl-input:not(:placeholder-shown) + .fl-label { top: 14px; font-size: 11px; color: #2563eb; }

.ei { width: 300px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.ei-label { display: block; margin-bottom: 6px; font-size: 13px; font-weight: 600; color: #374151; }
.ei-input { width: 100%; padding: 11px 14px; box-sizing: border-box; border: 1px solid #ef4444; border-radius: 8px; background: #fef2f2; font-size: 14px; color: #111827; }
.ei-input:focus { outline: none; box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.2); }
.ei-msg { margin: 6px 0 0; font-size: 12px; color: #b91c1c; }

.si { width: 300px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.si-label { display: block; margin-bottom: 6px; font-size: 13px; font-weight: 600; color: #374151; }
.si-input { width: 100%; padding: 11px 14px; box-sizing: border-box; border: 1px solid #22c55e; border-radius: 8px; background: #f0fdf4; font-size: 14px; color: #111827; }
.si-input:focus { outline: none; box-shadow: 0 0 0 3px rgba(34, 197, 94, 0.2); }
.si-msg { margin: 6px 0 0; font-size: 12px; color: #15803d; }

.di { width: 300px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.di-label { display: block; margin-bottom: 6px; font-size: 13px; font-weight: 600; color: #9ca3af; }
.di-input { width: 100%; padding: 11px 14px; box-sizing: border-box; border: 1px solid #e5e7eb; border-radius: 8px; background: #f3f4f6; font-size: 14px; color: #9ca3af; cursor: not-allowed; }
.di-note { margin: 6px 0 0; font-size: 12px; color: #9ca3af; }

.sz { display: flex; flex-direction: column; gap: 12px; width: 300px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.sz-input { width: 100%; box-sizing: border-box; border: 1px solid #d1d5db; border-radius: 8px; background: #fff; color: #111827; }
.sz-input:focus { outline: none; border-color: #2563eb; box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.18); }
.sz-sm { padding: 6px 10px; font-size: 12px; }
.sz-md { padding: 10px 14px; font-size: 14px; }
.sz-lg { padding: 14px 18px; font-size: 17px; border-radius: 10px; }
